#!/usr/bin/env node
/**
 * bundle-mcp.js
 *
 * Produces `mcp-server/index.bundled.js`, a single self-contained file with
 * the `@modelcontextprotocol/sdk` + `zod` (transitive) inlined so the
 * packaged VSIX does not need any `node_modules` to run the MCP server.
 *
 * The original `mcp-server/index.js` is left untouched so dev installs
 * (where `node_modules` exists) keep using the real require() chain.
 * The bundled file is what VS Code's stdio spawner and `portpilot-mcp`
 * bin entry point at, so production is unaffected by dev path.
 *
 * Usage:
 *   node scripts/bundle-mcp.js                # default output path
 *   node scripts/bundle-mcp.js --check        # exit 1 if bundle is stale
 */

const { execFileSync } = require("child_process");
const fs = require("fs");
const path = require("path");

const args = new Set(process.argv.slice(2));
const CHECK_ONLY = args.has("--check");

const repoRoot = path.resolve(__dirname, "..");
const entry = path.join(repoRoot, "mcp-server", "index.js");
const out = path.join(repoRoot, "mcp-server", "index.bundled.js");

function fail(msg) {
  console.error("✗", msg);
  process.exit(1);
}

function haveEsbuild() {
  try {
    const localBin = path.join(repoRoot, "node_modules", ".bin", "esbuild");
    if (fs.existsSync(localBin)) return localBin;
  } catch { /* ignore */ }
  // Fall back to npx — resolves via PATH and dev cache.
  return "npx";
}

function findEsbuild() {
  try {
    const v = execFileSync(
      haveEsbuild(),
      ["--version"],
      { cwd: repoRoot, stdio: ["ignore", "pipe", "pipe"] }
    ).toString().trim();
    return v;
  } catch (e) {
    fail(
      "esbuild is not installed. Run `npm install --save-dev esbuild` first.\n" +
      "  " + (e.stderr ? e.stderr.toString().split("\n")[0] : e.message)
    );
  }
}

function runBundle(bin) {
  // CommonJS output (matches Node 24 + Node 18+ default CJS resolver used by
  // VS Code's stdio spawner). Bundle everything; mark the SDK + zod as
  // external=false (inline) but keep Node built-ins external.
  const args = [
    entry,
    "--bundle",
    "--platform=node",
    "--format=cjs",
    "--target=node18",
    "--outfile=" + out,
    "--log-level=warning",
    "--legal-comments=none",
    // The MCP server installs a `Module._resolveFilename` hook that maps
    // `require("vscode")` to its bundled stub at runtime. esbuild cannot
    // see that hook, so mark `vscode` as external and let runtime resolve
    // it. Any other non-builtin modules can stay external too — node
    // built-ins (node:* + fs/path/...) are already auto-external.
    "--external:vscode",
    "--banner:js=" +
      "// Auto-generated by scripts/bundle-mcp.js — do not edit by hand.",
    "--footer:js=" +
      "// End of bundle.",
  ];
  execFileSync(bin, args, { cwd: repoRoot, stdio: "inherit" });
}

function fileNonEmpty(p) {
  try { return fs.statSync(p).size > 0; } catch { return false; }
}

function main() {
  if (!fs.existsSync(entry)) fail(`Missing entry: ${entry}`);
  const bin = haveEsbuild();
  const version = findEsbuild();
  console.log(`esbuild ${version}`);

  if (CHECK_ONLY) {
    if (!fileNonEmpty(out)) fail(`Bundle missing or stale: ${out}`);
    console.log(`✓ bundle present: ${out} (${fs.statSync(out).size} bytes)`);
    process.exit(0);
  }

  console.log(`Bundling ${path.relative(repoRoot, entry)} → ${path.relative(repoRoot, out)}`);
  runBundle(bin);
  if (!fileNonEmpty(out)) fail(`Bundle was not produced at ${out}`);
  console.log(`✓ bundle written: ${out} (${fs.statSync(out).size} bytes)`);
}

main();